const PDB={};PRICEDB.forEach(([g,L])=>L.forEach(([n,u,p,s])=>PDB[n.toLowerCase()]={n,u,p,g,s}));
const PLEVEL={disc:[1,"Discounter"],super:[1.18,"Supermarkt"],bio:[1.65,"Bio"]};
function dbFind(t){const k=t.toLowerCase().trim();if(PDB[k])return PDB[k];const c=Object.values(PDB).filter(x=>x.n.toLowerCase().startsWith(k)||k.startsWith(x.n.toLowerCase()));if(c.length)return c.sort((a,b)=>a.n.length-b.n.length)[0];
  const w=Object.values(PDB).find(x=>x.n.toLowerCase().split(/[\s-]/).some(p=>p.length>3&&k.includes(p)));return w||null}
function dbExact(t){const k=String(t||'').toLowerCase().trim();if(!k)return null;if(PDB[k])return PDB[k];const st=w=>w.replace(/(en|n|e|s)$/,'');const ks=st(k);return Object.values(PDB).find(x=>{const n=x.n.toLowerCase();return st(n)==ks&&ks.length>=3})||null}
function phAdd(n,p,t){if(!(p>0))return;const sh=shopS();sh.ph=sh.ph||{};const k=String(n).toLowerCase().trim();const L=sh.ph[k]=sh.ph[k]||[];const d=ymd(t||Date.now());const ex=L.find(x=>x[0]==d);if(ex)ex[1]=p;else L.push([d,Math.round(p*100)/100]);L.sort((a,b)=>a[0]<b[0]?-1:1);if(L.length>60)L.shift()}
function shopKnown(k){const sh=shopS();k=k.toLowerCase().trim();if(sh.prices[k])return{p:sh.prices[k],est:false};const d=dbExact(k);if(d)return{p:dbPrice(d),est:!d.s||(sh.level&&sh.level!='disc'),unit:d.u+(d.s&&!(sh.level&&sh.level!='disc')?' · Bon '+d.s:'')};const a=sh.aiP&&sh.aiP[k];return a?{p:dbPrice(a),est:true,unit:(a.u?a.u+' · ':'')+'KI-Schätzung'}:null}
function shopMatch(){const sh=shopS();sh.unk=sh.unk||{};let n=0;sh.items.forEach(x=>{if(x.p)return;const k=x.n.toLowerCase(),f=shopKnown(k);if(f){x.p=f.p;x.est=f.est;if(f.unit&&!x.unit)x.unit=f.unit;x.unk=false;n++}});
  Object.keys(sh.unk).forEach(k=>{if(shopKnown(k))delete sh.unk[k]});return n}
function shopWeekly(){const sh=shopS();sh.unk=sh.unk||{};if(Date.now()-(sh.lastSync||0)<7*864e5)return;sh.lastSync=Date.now();const n=shopMatch();if(n){save();toast(n+' Preis'+(n>1?'e':'')+' auf dem Einkaufszettel ergänzt.')}else save()}
function openShopPrices(){const sh=shopS(),K=Object.keys(sh.unk||{});if(!K.length){toast('Alle Artikel haben einen Preis.');return}const close=()=>{$('sheetRoot').innerHTML='';render()};
  $('sheetRoot').innerHTML=`<div class="scrim" id="scrim"></div><div class="sheet" role="dialog" aria-label="Preise nachtragen"><div class="sheet-h"><button id="spX">Abbrechen</button><b>Preise nachtragen</b><button id="spS" style="font-weight:600">Sichern</button></div>
   <div class="sheet-b"><div class="note" style="padding:0">Diese Artikel kennt die App noch nicht. Trag den Preis vom Kassenbon ein. Er wird gemerkt und künftig automatisch verwendet. Leere Felder bleiben in der Liste.</div>
   <div class="group">${K.map((k,i)=>`<div class="cell plain"><label for="spP${i}" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis">${esc(sh.unk[k].n)}</label><input id="spP${i}" inputmode="decimal" placeholder="€" style="max-width:100px;text-align:right"><button class="del" data-spd="${esc(k)}" aria-label="${esc(sh.unk[k].n)} vergessen">${I('minus',20)}</button></div>`).join('')}</div></div></div>`;
  $('scrim').onclick=$('spX').onclick=close;
  document.querySelectorAll('[data-spd]').forEach(b=>b.onclick=()=>{delete sh.unk[b.dataset.spd];save();b.closest('.cell').remove();if(!Object.keys(sh.unk).length)close()});
  $('spS').onclick=()=>{K.forEach((k,i)=>{const el=$('spP'+i);if(!el)return;const v=pNum(el.value);if(!isNaN(v)&&v>0){sh.prices[k]=v;delete sh.unk[k];phAdd(k,v)}});const n=shopMatch();save();close();toast(n?n+' Artikel auf dem Zettel aktualisiert.':'Preise gemerkt.')}}
