/* ---------- planning tools: Abo-Radar, Jahresplaner, Notgroschen, Monatsrückblick ---------- */
const ABOCAT=/abo|stream|spotify|apps|software|telekom|mobilfunk|sport|versicher|gebühr|icloud|cloud|mitglied|gez/i;
function addPer(d,pp,k=1){const x=new Date(d);if(!pp)return x;if(pp.u=='d')x.setDate(x.getDate()+pp.n*k);else if(pp.u=='w')x.setDate(x.getDate()+7*pp.n*k);else if(pp.u=='m')x.setMonth(x.getMonth()+pp.n*k);else x.setFullYear(x.getFullYear()+pp.n*k);return x}
function contractNext(c){if(c.state=='cancelled'){const d=new Date((c.next||c.start)+'T12:00');return{d,kd:null}}let d=new Date((c.next||c.start)+'T12:00');let g=0;const st=c.renew||c.term||{u:'y',n:1};while(d<now&&g++<600)d=addPer(d,st);let kd=c.notice?addPer(d,c.notice,-1):null;while(kd&&kd<now&&g++<600){d=addPer(d,st);kd=addPer(d,c.notice,-1)}return{d,kd}}
