  const kInfo=c=>{if(!c)return `<span class="s" style="color:var(--muted)">Keine Kündigungsfrist hinterlegt</span>`;if(c.state=='cancelled'){const x=contractNext(c);return `<span class="s" style="color:var(--muted)">Gekündigt · endet ${x.d.toLocaleDateString('de-DE')}</span>`}const x=contractNext(c),dl=x.kd?Math.ceil((x.kd-now)/864e5):null;
    return x.kd?`<span class="s" style="color:${dl<=30?'var(--bad)':dl<=60?'var(--warn)':'var(--muted)'};font-weight:${dl<=30?600:400}">${dl<=0?'Frist für diese Runde verpasst':'Kündigen bis '+x.kd.toLocaleDateString('de-DE')+' · noch '+dl+' Tage'}</span>`:`<span class="s" style="color:var(--muted)">${c.auto?'Verlängert sich am':'Endet am'} ${x.d.toLocaleDateString('de-DE')}</span>`};
