/* Eine Quelle für alles, was im Sinking-Funds-Topf angespart wird: S.goals. Jahresplaner = Sparziele mit Fälligkeitsmonat (m), jährlich wiederkehrend; Projekte können ein Sparziel haben (g.proj / x.goal). */
const gSaved=g=>(g.dep||[]).reduce((s,d)=>s+d.a,0);
const goalsAct=()=>(S.goals||[]).filter(g=>!g.done&&!g.dropped);
/* v237: Sinking Funds = Summe der Zielraten. Ziele mit Termin rechnen ihre Rate selbst (Jahresplan), Ziele ohne Termin haben eine eigene Monatsrate (g.rate). */
function sinkRates(){const Y={};try{yplanStatus().forEach(x=>{if(x.g)Y[x.g.id]=x})}catch(e){}return goalsAct().map(g=>{const y=Y[g.id];const r=y?(y.skipNext?0:y.need):Math.min(+g.rate||0,Math.max(g.ziel-gSaved(g),0));return{g,rate:Math.round(r*100)/100,dated:!!y}})}
function sinkSum(){return Math.round(sinkRates().reduce((s,x)=>s+x.rate,0))}
function migSink(){if(S.sink3&&!S.sinkIn&&sinkAcc()){S.sinkIn={};for(let o=-1;o>-60;o--){const P=period(o);if(P.s.getTime()<S.sink3)break;S.sinkIn[pkey(P)]=sinkSum()}}if(S.sink3&&S.sinkExtra==null&&sinkAcc()){S.sinkExtra=Math.max(Math.round((S.sinkOld||0)-sinkSum()),0);setTimeout(()=>{try{save()}catch(e){}},0)}if(S.sink3||!sinkAcc())return;const sn=sinkAcc(),B=S.budgets[sn]||0,R=sinkRates(),N=R.filter(x=>x.dated).reduce((s,x)=>s+x.rate,0),U=R.filter(x=>!x.dated&&!(x.g.rate>0));
  const L=Math.max(B-N,0);U.forEach(x=>{x.g.rate=Math.round(L/U.length)});S.sink3=period(1).s.getTime();S.sinkOld=B;if(S.sinkExtra==null)S.sinkExtra=Math.max(Math.round(B-sinkSum()),0);setTimeout(()=>{try{save()}catch(e){}},0)}
function sinkPot(){const sa=sinkAcc(),bal=sa?calc(sa).rest:0,alloc=goalsAct().reduce((s,g)=>s+gSaved(g),0);return{sa,bal,alloc,free:bal-alloc}}
function migYplan(){if(!S.yplan||!S.yplan.length){if(S.yplan)delete S.yplan;return}S.goals=S.goals||[];const it=S.yplan.map(x=>{const d=yplanNext(x);return{x,d}}).sort((a,b)=>a.d-b.d);let free=Math.max(0,sinkPot().free);
  it.forEach(({x})=>{const g={id:'y'+x.id,n:x.n,ziel:x.a,m:x.m,yearly:true,from:'Jahresplaner',t:Date.now(),dep:[],skip:x.skip||[]};const got=Math.min(x.a,free);if(got>=1){g.dep.push({a:Math.round(got*100)/100,t:Date.now(),src:'Übernahme aus dem Jahresplaner'});free-=got}if(!S.goals.some(q=>q.id==g.id))S.goals.push(g)});delete S.yplan;save()}
function goalDistribute(){const P=sinkPot();let free=Math.floor(Math.max(0,P.free)*100)/100;if(free<1){toast('In Sinking Funds ist gerade nichts frei.');return}const sn=JSON.stringify(S.goals),it=yplanStatus().filter(x=>x.src=='eigen'&&x.need>0),done=[];
  it.forEach(x=>{if(free<1)return;const a=Math.min(free,Math.round(Math.min(x.need,x.a-x.got)*100)/100);if(a>=1){x.g.dep.push({a,t:Date.now(),src:'Monatsrate'});free-=a;done.push(x.n)}});
  if(!done.length){toast('Alle Ziele sind für diesen Monat bedient.');return}save();render();toast('Monatsrate verteilt: '+done.join(', ')+'.',()=>{S.goals=JSON.parse(sn);save();render()})}
function potHtml(SP,dist){SP=SP||sinkPot();if(!SP.sa)return '';const zr=sinkSum(),ex=+S.sinkExtra||0;/* v253: Sinking Funds als Bestand: gebunden für Ziele + frei für Sonstiges */
 return `<div class="mmcard potc"><div class="pot-r"><span>Sinking Funds · Bestand</span><b class="${SP.bal<0?'out':''}">${eur0(SP.bal)}</b></div><div class="nsbar"><i style="width:${SP.bal>0?Math.min(100,SP.alloc/SP.bal*100).toFixed(0):0}%;background:${SP.free<0?'var(--warn)':'var(--sink)'}"></i></div><div class="ns-f"><span>für Ziele gebunden <b>${eur0(SP.alloc)}</b></span><span>${SP.free<0?'fehlt':'frei für Sonstiges'} <b>${eur0(Math.abs(SP.free))}</b></span></div>${SP.free<0?`<div class="note" style="padding:6px 0 0">Der Bestand reicht gerade nicht für alles, was für Ziele zurückgelegt ist. Mit dem nächsten Zufluss gleicht sich das aus, oder nimm bei einem Ziel etwas zurück.</div>`:''}<div class="ns-f" style="margin-top:6px"><span>Zufluss pro Monat <b>${eur0(zr+ex)}</b></span><button class="ed-link" id="sinkEx">Ziele ${eur0(zr)} + Sonstiges ${eur0(ex)} ✎</button></div>${dist&&SP.free>=1?'<button class="btn soft" id="ypDist" style="margin:8px 0 0">Freies Geld auf fällige Ziele verteilen</button>':''}</div>`}
function sinkExEdit(){const v=prompt('Fester Betrag pro Monat für sonstige, nicht monatliche Ausgaben (zusätzlich zu den Zielraten):',String(+S.sinkExtra||0).replace('.',','));if(v==null)return;const n=pNum(v);if(isNaN(n)||n<0){toast('Bitte einen Betrag eingeben.');return}S.sinkExtra=Math.round(n*100)/100;if(!S.sink3||S.sink3>period(0).s.getTime())S.sink3=period(0).s.getTime();save();render()}
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('#sinkEx'))sinkExEdit()});
function projLinkGoal(x){const m=x.from?new Date(x.from+'T12:00').getMonth()+1:null;const g=goalNew({n:x.n,ziel:x.bud,m:m||undefined,from:'Projekt',proj:x.id});x.goal=g.id;return g}
function goalNew(o){S.goals=S.goals||[];const g=Object.assign({id:uid(),t:Date.now(),dep:[],from:'selbst'},o);S.goals.push(g);return g}
const goalOf=x=>x&&x.goal?(S.goals||[]).find(g=>g.id==x.goal&&!g.dropped):null;
const projBud=x=>{const g=goalOf(x);return g?g.ziel:(x.bud||0)};
function yplanItems(){const it=goalsAct().filter(g=>g.m).map(g=>({id:g.id,n:g.n,a:g.ziel,m:g.m,src:'eigen',g,skip:g.skip,yearly:g.yearly,proj:g.proj}));(S.rec||[]).filter(r=>r.type=='out'&&(r.every||1)>=6).forEach(r=>{const s=new Date((r.start||ymd(Date.now()))+'T12:00');it.push({id:'r'+r.id,n:r.n,a:r.a,m:s.getMonth()+1,src:'dauerauftrag',every:r.every})});return it}
