function bindVaultSet(){if(setView!='ng')return;
  if($('vaultShow'))$('vaultShow').onchange=()=>{S.vaultHide=!$('vaultShow').checked;save();render()};
  document.querySelectorAll('[data-vacc]').forEach(c=>c.onchange=()=>{const a=acc(c.dataset.vacc);if(c.checked){a.rolle='vermoegen';setSperre(a,'tabu',true)}else if(a.rolle=='vermoegen')delete a.rolle;save();render();toast(c.checked?a.n+' liegt jetzt im Vermögen und ist tabu.':a.n+' ist nicht mehr im Vermögen. Es bleibt tabu, bis du es unter Regeln freigibst.')});
  document.querySelectorAll('[data-vrec]').forEach(b=>b.onclick=()=>openRec(+b.dataset.vrec));
  if($('vRecNew'))$('vRecNew').onclick=()=>{const pa=pufAcc();openRec(-1,{type:'tr',b:pa?pa.n:ALL[0],to:vaultAccs()[0]||vermAcc(),c:'',n:'Sparrate',every:1})};
  if($('vOnce'))$('vOnce').onclick=()=>openEinzahlung();
  if($('vbSet'))$('vbSet').onclick=()=>openVaultBase();if($('vNewAcc'))$('vNewAcc').onclick=()=>openVaultNew();
  document.querySelectorAll('[data-vae]').forEach(b=>b.onclick=()=>{setView='acct:'+b.dataset.vae;render();scrollTo(0,0)});
  if($('vGoal'))$('vGoal').onchange=()=>{S.vaultGoal=pNum($('vGoal').value)||null;save();render()}}
function reviewData(o){const p=period(o),L=RX().filter(e=>inP(e,p)&&!isPlan(e)),bs=BUDG.map(b=>({b,c:calc(b,o)})),by={};L.filter(e=>e.type=='out'&&TOT.includes(e.b)).forEach(e=>by[e.c]=(by[e.c]||0)+e.a);
  const top=Object.entries(by).sort((a,b)=>b[1]-a[1]).slice(0,3),big=L.filter(e=>e.type=='out'&&TOT.includes(e.b)).sort((a,b)=>b.a-a.a)[0];
  const ws=S.wish.filter(w=>w.dt&&inP({t:w.dt},p)),gone=ws.filter(w=>w.s=='verworfen'),bought=ws.filter(w=>w.s=='gekauft'),ov=(S.ovrLog||[]).filter(x=>inP({t:x.t},p));
  const good=[],bad=[];bs.forEach(x=>{if(x.c.rest>=0&&x.c.used>0)good.push(`${x.b} im Budget (${eur0(x.c.rest)} übrig)`);else if(x.c.rest<0)bad.push(`${x.b} überzogen um ${eur0(-x.c.rest)}`)});
  if(gone.length)good.push(`${gone.length} Wünsche losgelassen, ${eur0(gone.reduce((s,w)=>s+w.p,0))} gespart`);if(ov.length)bad.push(`Notfallbremse ${ov.length}× gelöst`);if(bought.length)good.push(`${bought.length} Wunsch bewusst gekauft`);
  {const pb=S.pension?bavMon():0;if(pb>0)good.push(`${eur0(pb)} in die Betriebsrente gespart (direkt vom Gehalt)`)}
  return{p,bs,top,big,good,bad,gone,ov}}
/* investments of a month into a depot account: only data from the Vermögen tab (Sparpläne + erfasste Käufe) */
function invMonth(n,o){const D=depot().filter(h=>h.to==n||(!h.to&&/etf|depot/i.test(n)&&h.type!='krypto')||(!h.to&&/krypto/i.test(n)&&h.type=='krypto'));if(!D.length)return null;
  const P=period(o),s0=P.s.getTime(),e0=P.e.getTime(),now0=Date.now();let b=0,pl=0;
  /* eine Quelle: Ereignisse aus posEvents (echte + rechnerische Sparplan-Ausführungen, ohne Nachträge); geplant über recDue/recA */
  D.forEach(h=>{posEvents(h).forEach(x=>{if(x.hist||x.t<s0||x.t>=e0||x.t>now0)return;b+=x.type=='sell'?-(x.q*x.p-(x.fee||0)):x.type=='plan'?txAmt(x):x.q*x.p+(x.fee||0)});
    const r=h.rid&&(S.rec||[]).find(x=>x.id==h.rid);if(r){if(r.paused||(r.end&&r.end<ymd(P.s.getTime())))return;const d=recDue(r,P);if(d&&d.getTime()>now0)pl+=recA(r,P)}
    else if(h.rate&&h.plan&&!h.paused){const d=dueIn(P.s.getFullYear(),P.s.getMonth()+(dueIn(P.s.getFullYear(),P.s.getMonth(),h.day)<P.s?1:0),h.day);if(d<P.e&&d.getTime()>now0)pl+=h.rate}});
  return{b:Math.round(b*100)/100,pl}}
function anaData(o){const p=period(o),pp=period(o-1),V=vaultAccs(),pa=pufAcc(),L=RX().filter(e=>inP(e,p)&&!isPlan(e)&&!e.corr),LP=RX().filter(e=>inP(e,pp)&&!isPlan(e)&&!e.corr);
  const sum=(A,f)=>A.filter(f).reduce((s,e)=>s+e.a,0),inc=A=>sum(A,e=>e.type=='in'),out=A=>sum(A,e=>e.type=='out');
  const intoV=e=>(e.type=='tr'&&V.includes(e.to)&&!V.includes(e.b))||(e.type=='in'&&V.includes(e.b)),saved=sum(L,intoV),goalDep=S.goals.reduce((s,g)=>s+g.dep.filter(d=>inP({t:d.t},p)).reduce((q,d)=>q+d.a,0),0);
  const fix=pa?sum(L,e=>e.b==pa.n&&e.type=='out'&&isRecE(e)):0,oneK=pa?sum(L,e=>e.b==pa.n&&e.type=='out'&&!isRecE(e)):0,budUsed=TOT.reduce((s,b)=>s+calc(b,o).used,0);
  const accs=S.accts.map(a=>{const n=a.n,c=calc(n,o),A=L;return{n,col:a.col,k:a.kind,in:sum(A,e=>e.type=='in'&&e.b==n),out:sum(A,e=>e.type=='out'&&e.b==n),trI:sum(A,e=>e.type=='tr'&&e.to==n),trO:sum(A,e=>e.type=='tr'&&e.b==n),end:c.rest,start:a.kind=='konto'?calc(n,o-1).rest:null,tot:c.total,used:c.used,inv:invMonth(n,o)}}).filter(x=>x.in||x.out||x.trI||x.trO||x.k=='konto');
  const byC={};L.filter(e=>e.type=='out').forEach(e=>{const k=e.c||'Sonstiges';byC[k]=byC[k]||{v:0,n:0,acc:{}};byC[k].v+=e.a;byC[k].n++;byC[k].acc[e.b]=1});
  const cats=Object.entries(byC).sort((a,b)=>b[1].v-a[1].v);
  const rec=(S.rec||[]).map((r,i)=>{const be=L.find(e=>e.rid==r.id);return{r,booked:!!be,amt:be?be.a:recA(r,p),adj:be?be.adj:adjOf(r,p)}}).filter(x=>x.r.type=='tr'&&V.includes(x.r.to)&&(x.booked||(!x.r.paused&&recDue(x.r,p))));
  const outs=L.filter(e=>e.type=='out'),wd=[0,0,0,0,0,0,0];outs.forEach(e=>wd[new Date(e.t).getDay()]+=e.a);const wmax=wd.indexOf(Math.max(...wd));
  const kons=sum(outs,e=>KONSUM.includes(e.c)),varOut=sum(outs,e=>!isRecE(e)),recOut=sum(outs,e=>isRecE(e));
  const ws=S.wish,nw=ws.filter(w=>inP({t:w.t},p)).length,gone=ws.filter(w=>w.dt&&inP({t:w.dt},p)&&w.s=='verworfen'),bought=ws.filter(w=>w.dt&&inP({t:w.dt},p)&&w.s=='gekauft');
  const I1=inc(L),O1=out(L),I0=inc(LP),O0=out(LP);
  return{p,I1,O1,I0,O0,saved,goalDep,fix,oneK,budUsed,accs,cats,rec,wd,wmax,kons,varOut,recOut,cnt:outs.length,days:p.len||30,nw,gone,bought,quote:I1?saved/I1:0}}
