     <div class="srow"><div class="srow-h"><span>Insgesamt ins Vermögen</span><span></span><b class="in">${eur(A.saved)}</b></div>${A.goalDep?`<div class="s" style="font-size:12px;color:var(--muted)">Dazu ${eur(A.goalDep)} für Sparziele zurückgelegt</div>`:''}</div></div></div>
   <div class="sec"><div class="sh">Ausgaben nach Kategorie</div><div class="mmcard">${A.cats.slice(0,10).map(([c,x])=>`<div class="srow"><div class="srow-h"><span>${esc(c)} <small style="color:var(--muted)">${x.n}×</small></span><span class="s" style="font-size:12px;color:var(--muted)">${Object.keys(x.acc).map(b=>esc(SHORT[b]||b)).join(', ')}</span><b>${eur(x.v)}</b></div><div class="bar"><i style="width:${(x.v/cmax*100).toFixed(0)}%;background:var(--accent)"></i></div></div>`).join('')||'<div class="empty">Keine Ausgaben.</div>'}</div></div>
