function bindPlan(){const on=(id,f)=>{const el=$(id);if(el)el.onclick=f};
  const addY=(n,a,m)=>{if(!n||!a)return;goalNew({n,ziel:a,m:+m,yearly:true,from:'Jahresplaner'});save();render();toast(n+' ist jetzt ein Sparziel – auch unter Planen › Ziele.')};
  on('ypAdd',()=>addY($('ypN').value.trim(),pNum($('ypA').value),$('ypM').value));
  document.querySelectorAll('[data-ysug]').forEach(b=>b.onclick=()=>{const[n,a,m]=b.dataset.ysug.split('|');addY(n,+a,m)});
  document.querySelectorAll('[data-ypx]').forEach(b=>b.onclick=()=>{const g=(S.goals||[]).find(x=>x.id==b.dataset.ypx);if(!g)return;const sn=JSON.stringify(S.goals);if(gSaved(g)>0)g.dropped=Date.now();else S.goals=S.goals.filter(x=>x!==g);save();render();toast(g.n+' entfernt'+(gSaved(g)>0?' – '+eur0(gSaved(g))+' sind wieder frei in Sinking Funds':'')+'.',()=>{S.goals=JSON.parse(sn);save();render()})});
  on('ypDist',()=>goalDistribute());
  ['ngT','ngV','ngR'].forEach(id=>{const el=$(id);if(el)el.onchange=()=>{S.ng=S.ng||{};const v=el.value.trim();if(id=='ngT')S.ng.target=pNum(v)||null;if(id=='ngV')S.ng.manual=v===''?null:pNum(v);if(id=='ngR')S.ng.rate=pNum(v)||150;save();render()}});
  on('rvP',()=>{S.revOff=(S.revOff??-1)-1;render()});on('rvN',()=>{if((S.revOff??-1)<0){S.revOff=(S.revOff??-1)+1;render()}});
  if($('rvG'))$('rvG').onchange=()=>{S.reviews=S.reviews||{};S.reviews[pkey(period(S.revOff??-1))]={t:$('rvG').value};save()};
  on('rvCopy',e=>{e.stopPropagation();pennyTalk('rev')})}
/* small celebration */
const growFrom={};
function celebrate(msg,big){const r=$('modalRoot'),C=['#6E4BD8','#D946EF','#F0657A','#22A699','#F2A23A','#4F6BED','#1F9D6B'];
  const conf=big?Array.from({length:60},(_,i)=>`<i style="left:${Math.random()*100}%;background:${C[i%C.length]};animation-delay:${(Math.random()*.5).toFixed(2)}s;animation-duration:${(1.6+Math.random()*1.2).toFixed(2)}s;transform:rotate(${Math.random()*360|0}deg);${i%3?'':'border-radius:50%;'}"></i>`).join(''):'';
  r.innerHTML=`<div class="cele ${big?'big':''}" role="status">${conf?`<div class="confetti">${conf}</div>`:''}<div class="cele-ring">${I(big?'target':'piggy',34)}</div><b>${esc(msg)}</b>${big?'<span>Du hast es geschafft. Jetzt darfst du bewusst kaufen.</span>':''}</div>`;
  setTimeout(()=>{if(r.querySelector('.cele'))r.innerHTML=''},big?3200:1700)}
